// A fast path for the frame JSON of `pc_encoder_frame_json[_at]`.
//
// A data frame carries thousands of dots, and `jsonDecode` turns each into a Map with
// nested Maps and boxed numbers: for profile L that is over a hundred thousand short-lived
// objects per frame, which costs more than the Reed-Solomon coding in Rust and, because
// isolates of one app share a heap, also pauses *other* isolates at every young-generation
// collection. The dots array is machine-generated by serde with a fixed field order, so it
// is read here straight from the UTF-8 bytes into typed arrays without allocating per dot.
// Everything else (header, anchors, swatches, ...) is small and goes through `jsonDecode`.
//
// The fast path is strict: any deviation from the expected layout throws a
// [FormatException] and the caller falls back to `jsonDecode` for the whole document.

import 'dart:convert';

import 'package:flutter/foundation.dart';

import 'frame_spec.dart';

/// Parses the JSON text of one frame, given as UTF-8 [bytes].
///
/// [dotCountHint] sizes the dot arrays (the encoder knows the exact count).
/// Produces exactly the same [FrameSpec] as `FrameSpec.fromJson(jsonDecode(text))`.
FrameSpec parseFrameJsonBytes(Uint8List bytes, {int dotCountHint = 4096}) {
  try {
    return _fast(bytes, dotCountHint);
  } on FormatException {
    return _slow(bytes);
  } on RangeError {
    // Ran off the end of the buffer: not the layout we expect.
    return _slow(bytes);
  }
}

int _fallbacks = 0;

/// How often the strict fast path gave up and `jsonDecode` was used. For tests.
@visibleForTesting
int get debugFrameJsonFallbacks => _fallbacks;

/// Parses a dots array whose `[` is just before [start]. For tests.
@visibleForTesting
FrameDots parseDotsArray(Uint8List bytes, int start, {int hint = 16}) =>
    _DotsParser(bytes, start, hint).parse();

FrameSpec _slow(Uint8List bytes) {
  _fallbacks++;
  return FrameSpec.fromJson(
    jsonDecode(utf8.decode(bytes)) as Map<String, Object?>,
  );
}

// "dots":[
final Uint8List _dotsKey = Uint8List.fromList(utf8.encode('"dots":['));
final Uint8List _emptyDots = Uint8List.fromList(utf8.encode('"dots":[]'));

FrameSpec _fast(Uint8List b, int hint) {
  final keyAt = _find(b, _dotsKey);
  if (keyAt < 0) throw const FormatException('no dots array');
  final start = keyAt + _dotsKey.length;
  final parser = _DotsParser(b, start, hint);
  final dots = parser.parse();
  final end = parser.pos;

  // Everything but the dots, with an empty array in their place.
  final rest = Uint8List(keyAt + _emptyDots.length + (b.length - end));
  rest.setRange(0, keyAt, b);
  rest.setRange(keyAt, keyAt + _emptyDots.length, _emptyDots);
  rest.setRange(keyAt + _emptyDots.length, rest.length, b, end);
  final map = jsonDecode(utf8.decode(rest)) as Map<String, Object?>;
  return FrameSpec.fromJson(map, dots: dots);
}

int _find(Uint8List b, Uint8List key) {
  final first = key[0];
  final last = b.length - key.length;
  outer:
  for (var i = 0; i <= last; i++) {
    if (b[i] != first) continue;
    for (var j = 1; j < key.length; j++) {
      if (b[i + j] != key[j]) continue outer;
    }
    return i;
  }
  return -1;
}

const List<double> _pow10 = [
  1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10, 1e11, //
  1e12, 1e13, 1e14, 1e15, 1e16, 1e17, 1e18, 1e19, 1e20, 1e21, 1e22,
];

// Literal pieces between the values of one dot, in serde's field order.
final Uint8List _kQ = _lit('{"q":');
final Uint8List _kR = _lit(',"r":');
final Uint8List _kAtX = _lit(',"at":{"x":');
final Uint8List _kY = _lit(',"y":');
final Uint8List _kColor = _lit('},"color":');
final Uint8List _kSize = _lit(',"size":');

Uint8List _lit(String s) => Uint8List.fromList(utf8.encode(s));

class _DotsParser {
  _DotsParser(this.b, this.pos, int hint)
    : _cap = hint < 16 ? 16 : hint,
      _q = Int32List(hint < 16 ? 16 : hint),
      _r = Int32List(hint < 16 ? 16 : hint),
      _x = Float64List(hint < 16 ? 16 : hint),
      _y = Float64List(hint < 16 ? 16 : hint),
      _color = Uint8List(hint < 16 ? 16 : hint),
      _size = Uint8List(hint < 16 ? 16 : hint);

  final Uint8List b;
  int pos;
  int _n = 0;
  int _cap;
  Int32List _q, _r;
  Float64List _x, _y;
  Uint8List _color, _size;

  FrameDots parse() {
    if (pos < b.length && b[pos] == 0x5D) {
      pos++;
      return _finish();
    }
    while (true) {
      _dot();
      final c = b[pos++];
      if (c == 0x5D) break; // ]
      if (c != 0x2C) throw const FormatException('expected , or ]');
    }
    return _finish();
  }

  FrameDots _finish() => FrameDots.fromArrays(
    q: _fit(_q, _n),
    r: _fit(_r, _n),
    x: _fit(_x, _n),
    y: _fit(_y, _n),
    color: _fit(_color, _n),
    size: _fit(_size, _n),
  );

  static T _fit<T extends List<num>>(T l, int n) =>
      (l.length == n ? l : l.sublist(0, n)) as T;

  void _grow() {
    final cap = _cap * 2;
    _q = Int32List(cap)..setRange(0, _n, _q);
    _r = Int32List(cap)..setRange(0, _n, _r);
    _x = Float64List(cap)..setRange(0, _n, _x);
    _y = Float64List(cap)..setRange(0, _n, _y);
    _color = Uint8List(cap)..setRange(0, _n, _color);
    _size = Uint8List(cap)..setRange(0, _n, _size);
    _cap = cap;
  }

  void _dot() {
    if (_n == _cap) _grow();
    _expect(_kQ);
    _q[_n] = _int();
    _expect(_kR);
    _r[_n] = _int();
    _expect(_kAtX);
    _x[_n] = _double();
    _expect(_kY);
    _y[_n] = _double();
    _expect(_kColor);
    _color[_n] = _int();
    _expect(_kSize);
    _size[_n] = _int();
    if (b[pos++] != 0x7D) throw const FormatException('expected }'); // }
    _n++;
  }

  void _expect(Uint8List lit) {
    final p = pos;
    for (var i = 0; i < lit.length; i++) {
      if (b[p + i] != lit[i]) {
        throw FormatException('unexpected dot layout at byte $p');
      }
    }
    pos = p + lit.length;
  }

  int _int() {
    var p = pos;
    var neg = false;
    if (b[p] == 0x2D) {
      neg = true;
      p++;
    }
    final digitsAt = p;
    var v = 0;
    while (true) {
      final d = b[p] - 0x30;
      if (d < 0 || d > 9) break;
      v = v * 10 + d;
      p++;
      if (p - digitsAt > 18) throw const FormatException('integer too long');
    }
    if (p == digitsAt) throw const FormatException('expected an integer');
    pos = p;
    return neg ? -v : v;
  }

  /// A JSON number as a double, correctly rounded: Clinger's exact fast path when the
  /// decimal significand and exponent are small enough, `double.parse` otherwise.
  double _double() {
    final begin = pos;
    var p = pos;
    var neg = false;
    if (b[p] == 0x2D) {
      neg = true;
      p++;
    }
    var mant = 0;
    var digits = 0;
    var frac = 0;
    var seenDot = false;
    var exact = true;
    while (true) {
      final c = b[p];
      final d = c - 0x30;
      if (d >= 0 && d <= 9) {
        if (digits < 18) {
          mant = mant * 10 + d;
          if (mant != 0) digits++;
          if (seenDot) frac++;
        } else {
          exact = false;
        }
        p++;
      } else if (c == 0x2E && !seenDot) {
        seenDot = true;
        p++;
      } else {
        break;
      }
    }
    if (p == begin || (neg && p == begin + 1)) {
      throw const FormatException('expected a number');
    }
    var exp10 = -frac;
    if (b[p] == 0x65 || b[p] == 0x45) {
      p++;
      var eneg = false;
      if (b[p] == 0x2D) {
        eneg = true;
        p++;
      } else if (b[p] == 0x2B) {
        p++;
      }
      var e = 0;
      final eStart = p;
      while (true) {
        final d = b[p] - 0x30;
        if (d < 0 || d > 9) break;
        e = e * 10 + d;
        p++;
        if (p - eStart > 5) throw const FormatException('exponent too long');
      }
      if (p == eStart) throw const FormatException('bad exponent');
      exp10 += eneg ? -e : e;
    }
    pos = p;
    if (exact && mant <= 9007199254740992 && exp10 >= -22 && exp10 <= 22) {
      final m = mant.toDouble();
      final v = exp10 < 0 ? m / _pow10[-exp10] : m * _pow10[exp10];
      return neg ? -v : v;
    }
    return double.parse(String.fromCharCodes(b, begin, p));
  }
}
